export type Request = { id: string, protocolVersion: number, command: Command, };
export type ApiError = { code: string, message: string, };
export type Response = { id: string, result: Snapshot | null, error: ApiError | null, };
export type Role = "user" | "chief" | "deputy" | "worker" | "core";
export type Principal = { id: string, role: Role, provider: string | null, };
export type WorkflowTask = { id: string, dependencies: Array<string>, workspaceKey: string, goal: string, resourceKeys: Array<string> | null, };
export type WorkflowPlan = { id: string, version: number, tasks: Array<WorkflowTask>, };
export type TaskState = "pending" | "assigned" | "dispatching" | "running" | "cancelling" | "unknown" | "submitted" | "accepted" | "cancelled" | "retired";
export type TaskRun = { state: TaskState, worker: string | null, attempt: string | null, fence: number, evidence: Array<string>, verified: boolean, cancellationRequested: boolean | null, };
export type Advice = { task: string, suggestion: string, };
export type WorkflowState = { plan: WorkflowPlan | null, digest: string | null, approved: boolean, tasks: { [key in string]?: TaskRun }, advice: Array<Advice>, revisionRequested?: string | null, };
export type ReconcileOutcome = "not-started" | "running" | "submitted" | "cancelled";
